function metric(label,num,foot,icon,tone,tint){return `<section class="card metric-card" style="--tone:${tone};--tint:${tint}"><div class="metric-head"><span>${label}</span><i class="metric-icon">${icon}</i></div><div class="metric-number">${num}</div><div class="metric-foot"><strong>↑</strong>${foot}</div></section>`}
function activity(icon,title,sub,time){return `<div class="activity"><span class="activity-icon">${icon}</span><div><strong>${title}</strong><small>${sub}</small></div><time>${time}</time></div>`}

