function moduleTableRow(m,i){let cls=m.status==='已发布'?'green':m.status==='草稿'?'orange':'';return `<tr data-module-card data-name="${m.name}" data-status="${m.status}"><td><i class="checkbox" data-row-check></i></td><td><code class="route-code">MOD-${String(i+1).padStart(2,'0')}</code></td><td><div class="page-title-cell"><span class="page-cover" style="--from:${m.color};--to:${m.color}cc">${m.symbol}</span><div><strong>${m.name}</strong><small>${m.desc}</small></div></div></td><td>${[3,3,3,3,3,3,5,3,4][i]}</td><td>${m.units}</td><td>${m.tasks}</td><td>${m.version}</td><td><span class="tiny-tag ${cls}">${m.status}</span></td><td>2026-09-${29-i}<br><small style="color:#9aa4b3">运营小林</small></td><td><button class="table-action" data-edit-module-meta="${i}">编辑</button><button class="table-action" data-edit-module="${i}">内容编排</button><button class="table-action" data-module-more="${i}">更多</button></td></tr>`}

