function speakText(text){
  if(!text)return;
  if(!('speechSynthesis' in window)){toast('当前浏览器不支持语音试听','旁白文案仍可正常配置');return}
  window.speechSynthesis.cancel();
  const utterance=new SpeechSynthesisUtterance(text);utterance.lang='zh-CN';utterance.rate=.92;utterance.pitch=1.04;
  const voice=window.speechSynthesis.getVoices().find(v=>/zh|Chinese|中文/i.test(`${v.lang} ${v.name}`));if(voice)utterance.voice=voice;
  window.speechSynthesis.speak(utterance);toast('正在试听旁白',text.length>28?`${text.slice(0,28)}…`:text);
}

