document.addEventListener('input',e=>{if(e.target.id==='pageSearch')filterPages();if(e.target.id==='moduleSearch')filterModules();if(e.target.id==='heroTitleInput'){let h=document.querySelector('.hero-block h3');if(h)h.textContent=e.target.value}if(e.target.id==='heroDescInput'){let p=document.querySelector('.hero-block p');if(p)p.textContent=e.target.value}});
document.addEventListener('change',e=>{if(e.target.id==='pageModule'||e.target.id==='pageStatus')filterPages();if(e.target.id==='moduleStatus')filterModules();if(e.target.id==='previewState'){let preview=document.querySelector('#devicePreview');if(preview){preview.classList.remove('state-progress','state-new','state-done','state-locked');preview.classList.add(`state-${e.target.value}`)}let labels={progress:['进行中 1/10','已完成','未开始'],new:['未开始','未开始','未开始'],done:['已完成 10/10','已完成','已完成'],locked:['已锁定','已锁定','已锁定']};document.querySelectorAll('.category-tile small').forEach((x,i)=>x.textContent=labels[e.target.value][i]||labels[e.target.value][0]);toast('用户状态已切换',e.target.options[e.target.selectedIndex].text)}});
modalBackdrop.addEventListener('click',e=>{if(e.target===modalBackdrop)closeModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();let cards=[...document.querySelectorAll('.category-tile')];if(cards.length&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();let current=Math.max(0,cards.indexOf(document.activeElement));let next=e.key==='ArrowRight'?(current+1)%cards.length:(current-1+cards.length)%cards.length;cards[next].focus();speakText(cards[next].dataset.speak)}if(e.key==='Enter'&&document.activeElement?.classList.contains('category-tile'))speakText(document.activeElement.dataset.speak)});
navigate('dashboard');
